mapper.select:


    inner join sys_user u on u.user_name = ttaskout.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    ttaskout.del_flag = '0'
     and ttaskout.out_delivery_id = #{outDeliveryId}
     and ttaskout.out_delivery_detail_id = #{outDeliveryDetailId}
     and ttaskout.material_id = #{materialId}
     and ttaskout.predict_count = #{predictCount}
     and ttaskout.actual_count = #{actualCount}
     and ttaskout.status = #{status}
     and ttaskout.stock_id = #{stockId}


${params.dataScope}
